): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

/**
 * The issue's author, its assignee and every (non-deleted) comment author,
 * deduplicated and narrowed to org members who have not since been removed.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const commentAuthorIds = await commentRepo.listCommentAuthorIds(
    orgId,
    issueId,
  );

  const candidateIds = new Set<UserId>([
    issue.authorId,
    ...(issue.assigneeId === null ? [] : [issue.assigneeId]),
    ...commentAuthorIds,
  ]);

  const participants: UserId[] = [];
  for (const userId of candidateIds) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member !== null && member.status === "active") {
      participants.push(userId);
    }
  }

  return participants;
}

